function diagram(caption, alt, viewBox, drawing) {
  return {
    caption, alt,
    svg: `<svg viewBox="${viewBox}" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
      <g font-family="system-ui, sans-serif" font-size="17" fill="#26314a">${drawing}</g>
    </svg>`,
  };
}

